package fraymus.workspace;

import org.json.*;
import java.util.*;

/** Native evidence rendered through the existing canvas, independently checked before retention. */
final class PushReport {
    static JSONArray charts(JSONObject run){
        var samples=run.getJSONArray("samples");var intent=run.getJSONObject("plan").getJSONObject("intent");String crate=intent.getString("objectId");double duration=run.getJSONObject("final").getDouble("timeS");
        double[][] values=new double[6][samples.length()];double[] maxima=new double[6];Arrays.fill(maxima,.1);
        for(int i=0;i<samples.length();i++){var s=samples.getJSONObject(i);var b=PushPhysics.dynamic(s.getJSONArray("bodies"),crate);values[0][i]=PushVerify.distance(b.getJSONArray("position"),intent.getJSONArray("targetM"));values[1][i]=ObserverGeometry.norm(SpatialScene.vector(b.getJSONArray("velocity"),100));values[2][i]=ObserverGeometry.norm(SpatialScene.vector(s.getJSONArray("force"),100));values[3][i]=s.getInt("contacts");values[4][i]=s.getDouble("effortNs");values[5][i]=s.getDouble("pusherWorkJ");for(int k=0;k<6;k++)maxima[k]=Math.max(maxima[k],Math.abs(values[k][i]));}
        String[] labels={"Crate distance to target · m","Crate speed · m/s","Actual pusher force · N","Native pusher/crate contacts","Pusher force effort · N·s","Signed pusher work · J"};var out=new JSONArray();
        for(int k=0;k<6;k++){var points=new JSONArray();for(int i=0;i<samples.length();i++)points.put(new JSONArray(new double[]{Procedural.round(40+720*samples.getJSONObject(i).getDouble("timeS")/duration),Procedural.round(k==5?150-110*values[k][i]/maxima[k]:260-220*values[k][i]/maxima[k])}));out.put(new JSONObject().put("mode",labels[k]).put("durationS",duration).put("maximum",maxima[k]).put("minimum",k==5?-maxima[k]:0).put("values",new JSONArray(values[k])).put("points",points));}return out;
    }
    static JSONObject data(JSONObject run){return new JSONObject().put("verification",PushVerify.verify(run)).put("intent",run.getJSONObject("plan").getJSONObject("intent")).put("plan",run.getJSONObject("plan")).put("events",run.getJSONArray("events")).put("checkpoint",run.getJSONObject("checkpoint"));}
    static JSONArray checks(JSONObject g,JSONObject run){return new JSONArray().put(new JSONObject().put("selector","#push-result").put("expectText","Native contact task verified")).put(new JSONObject().put("selector","#push-samples").put("expectText",String.valueOf(run.getJSONArray("samples").length()))).put(new JSONObject().put("selector","#chart-label").put("expectText","Crate distance to target · m")).put(new JSONObject().put("selector","#chart-mode").put("action","click")).put(new JSONObject().put("selector","#chart-label").put("expectText","Crate speed · m/s")).put(new JSONObject().put("selector","#chart-reset").put("action","click")).put(new JSONObject().put("selector","#push-scope").put("expectText",PushPlan.SCOPE));}
    static JSONObject verifyView(JSONObject run,JSONObject actual){
        var expected=charts(run);var frames=actual.getJSONArray("frames");if(frames.length()!=6||!actual.getString("mode").equals(expected.getJSONObject(0).getString("mode")))throw new IllegalStateException("Observe every native pushing chart and reset");double max=0;int count=0;
        for(int f=-1;f<frames.length();f++){var frame=f<0?actual:frames.getJSONObject(f);var e=expected.getJSONObject(Math.max(0,f));if(!frame.getString("mode").equals(e.getString("mode")))throw new IllegalStateException("Pushing chart mode differs");var points=frame.getJSONArray("points");if(points.length()!=e.getJSONArray("points").length())throw new IllegalStateException("Pushing point count differs");for(int i=0;i<points.length();i++)for(int k=0;k<2;k++){double delta=Math.abs(points.getJSONArray(i).getDouble(k)-e.getJSONArray("points").getJSONArray(i).getDouble(k));if(!Double.isFinite(delta))throw new IllegalStateException("Nonfinite native pushing point");max=Math.max(max,delta);}if(f>=0)count+=points.length();}
        if(max>.002||!actual.optBoolean("pushVisible")||!data(run).similar(actual.getJSONObject("pushData")))throw new IllegalStateException("Visible pushing charts/plan/recovery data differ from original native evidence");return new JSONObject().put("passed",true).put("frames",6).put("observedPoints",count).put("maxError",max).put("originalDataVerified",true);
    }
    static JSONObject build(JSONObject run){
        var compact=new JSONObject(run.toString());var samples=new JSONArray();for(Object raw:compact.getJSONArray("samples")){var sample=(JSONObject)raw;var bodies=new JSONArray();for(Object body:sample.getJSONArray("bodies")){var b=(JSONObject)body;bodies.put(new JSONObject().put("id",b.getString("id")).put("position",b.getJSONArray("position")));}samples.put(new JSONObject().put("tick",sample.getInt("tick")).put("timeS",sample.getDouble("timeS")).put("bodies",bodies));}compact.put("samples",samples);compact.getJSONObject("final").remove("integration");
        try{byte[] raw=run.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);var bytes=new java.io.ByteArrayOutputStream();try(var gzip=new java.util.zip.GZIPOutputStream(bytes)){gzip.write(raw);}var packed=new JSONObject().put("format","fraynix.native-push-run-gzip-v1").put("rawSha256",MapDefinition.sha(raw)).put("rawBytes",raw.length).put("gzipBase64",Base64.getEncoder().encodeToString(bytes.toByteArray()));
            var csv=new StringBuilder("tick,time_s,crate_x_m,crate_y_m,crate_z_m,pusher_x_m,pusher_y_m,pusher_z_m,force_x_N,force_z_N,contacts,effort_Ns,pusher_work_J\n");var intent=run.getJSONObject("plan").getJSONObject("intent");for(Object value:run.getJSONArray("samples")){var s=(JSONObject)value;csv.append(s.getInt("tick")).append(',').append(s.getDouble("timeS"));for(String id:List.of(intent.getString("objectId"),intent.getString("pusherId")))for(Object number:PushPhysics.dynamic(s.getJSONArray("bodies"),id).getJSONArray("position"))csv.append(',').append(number);csv.append(',').append(s.getJSONArray("force").getDouble(0)).append(',').append(s.getJSONArray("force").getDouble(2)).append(',').append(s.getInt("contacts")).append(',').append(s.getDouble("effortNs")).append(',').append(s.getDouble("pusherWorkJ")).append('\n');}
            return new JSONObject().put("title","Verified native push · "+run.getJSONObject("definition").getString("title")).put("files",new JSONObject().put("index.html",HTML).put("run.json",compact.toString()).put("native-run.json",packed.toString()).put("charts.json",charts(run).toString()).put("proof.json",data(run).toString()).put("trace.csv",csv.toString())).put("sources",sources(run));
        }catch(Exception e){throw new IllegalStateException(e);}
    }
    static JSONArray sources(JSONObject run){return new JSONArray(List.of("spatial:"+run.getJSONObject("definition").getString("id")+":"+run.getJSONObject("definition").getString("sourceSha256"),"native-push-run:"+run.getString("id")));}
    static void checkSaved(JSONObject goal,JSONObject run,JSONObject artifact){var ref=goal.getJSONObject("report");if(!ref.getString("id").equals(artifact.getString("id"))||ref.getInt("version")!=artifact.getInt("version")||!ref.getString("sha256").equals(MeasurementStore.hash(artifact.getJSONObject("contents").toString()))||!sources(run).similar(artifact.getJSONArray("sources")))throw new IllegalStateException("Original pushing report/source changed");}
    static final String HTML="""
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Native contact pushing evidence</title><style>*{box-sizing:border-box}body{margin:0;background:#112a2e;color:#e3f1e8;font:15px/1.65 system-ui;overflow-wrap:anywhere}main{padding:24px;max-width:1100px;margin:auto}h1{font-size:30px}.cards,.controls{display:flex;gap:12px;flex-wrap:wrap}.cards>div{flex:1;min-width:120px;padding:14px;background:#22423d;border-radius:10px}b{display:block;font-size:22px}button,a{color:#d4f4e3}button{background:#2a5549;border:1px solid #89bdad;border-radius:8px;padding:10px;font:inherit}svg{width:100%;height:auto;background:#f2f5ee;border-radius:10px;margin:16px 0}.world{max-width:580px}pre{white-space:pre-wrap;background:#1b3c3d;border-radius:10px;padding:14px}</style><main><p>FRAYNIX / APPROACH PLANNING / CONTACT-DRIVEN NATIVE MOTION</p><h1 id="push-result">Loading native evidence…</h1><p id="push-scope"></p><div class="cards"><div><b id="push-samples"></b>native samples</div><div><b id="push-error"></b>crate error · m</div><div><b id="push-recovery"></b>measured recoveries</div><div><b id="push-force"></b>maximum force · N</div></div><p>Plan and measured paths in the floor plane: orange crate plan, red actual crate, blue actual pusher.</p><svg class="world" id="push-world" aria-label="Original obstacles and native pusher/crate paths"></svg><div class="controls"><button id="chart-mode">Next metric</button><button id="chart-reset">Reset chart</button><strong id="chart-label"></strong></div><svg viewBox="0 0 800 300" id="native-chart" aria-label="Actual native pushing measurements"><path d="M40 20V260H760" stroke="#537e6c" fill="none"/><polyline id="native-trace" stroke="#176651" stroke-width="2" fill="none"/></svg><p id="scale"></p><h2>Original plan, controller and recovery evidence</h2><p>The pusher receives bounded forces; the crate moves through native contacts. Jams require measured lack of progress and real contact. Recovery remains inside the original maximum force.</p><pre id="push-data"></pre><p><a href="run.json" download>Native sample JSON</a> · <a href="native-run.json" download>Complete per-tick native package</a> · <a href="trace.csv" download>Measured trajectory CSV</a> · <a href="proof.json" download>Original plan and verification</a></p><p>Declared synthetic physics and procedural retention. This does not train Ollama weights or establish universal robot control.</p></main><script>
(async()=>{const [run,charts,proof]=await Promise.all(['run.json','charts.json','proof.json'].map(async f=>(await fetch(f)).json()));const $=id=>document.getElementById(id),v=run.verification,intent=run.plan.intent,scene=run.definition;$('push-result').textContent=v.passed?'Native contact task verified':'Native contact task failed';$('push-scope').textContent=intent.scope;$('push-samples').textContent=run.samples.length;$('push-error').textContent=v.endpointErrorM.toFixed(6);$('push-recovery').textContent=v.recoveries;$('push-force').textContent=v.maxForceN.toFixed(3);$('push-data').textContent=JSON.stringify(proof,null,2);const svg=$('push-world'),ns='http://www.w3.org/2000/svg';const floor=scene.objects.find(o=>o.sourceId==='floor');svg.setAttribute('viewBox',[floor.position[0]-floor.size[0]/2-.3,floor.position[2]-floor.size[2]/2-.3,floor.size[0]+.6,floor.size[2]+.6].join(' '));function add(tag,attributes){const e=document.createElementNS(ns,tag);for(const[k,value]of Object.entries(attributes))e.setAttribute(k,String(value));svg.append(e);}for(const o of scene.objects)if(o.massKg===0&&o.sourceId!=='floor')add('rect',{x:o.position[0]-o.size[0]/2,y:o.position[2]-o.size[2]/2,width:o.size[0],height:o.size[2],fill:'#485e62'});const p=scene.objects.find(o=>o.id===intent.objectId),points=[[p.position[0],p.position[2]],...run.plan.actions.filter(a=>a.kind==='push').map(a=>[a.target[0],a.target[2]])];add('polyline',{points:points.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#d99728','stroke-width':.07});for(const[id,color]of [[intent.objectId,'#e45a47'],[intent.pusherId,'#317fba']])add('polyline',{points:run.samples.map(s=>{const b=s.bodies.find(b=>b.id===id);return b.position[0]+','+b.position[2];}).join(' '),fill:'none',stroke:color,'stroke-width':.045});let mode=0;function draw(){const c=charts[mode];$('chart-label').textContent=c.mode;$('native-trace').setAttribute('points',c.points.map(p=>p.join(',')).join(' '));$('scale').textContent='Time 0–'+c.durationS.toFixed(3)+' s · vertical '+c.minimum.toFixed(3)+' to '+c.maximum.toFixed(3)+' · every point from the actual native trace';}$('chart-mode').onclick=()=>{mode=(mode+1)%charts.length;draw();};$('chart-reset').onclick=()=>{mode=0;draw();};draw();})().catch(e=>{document.getElementById('push-result').textContent='Evidence loading failed: '+e.message;throw e;});
</script></html>
""";
}
